import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Heart, MapPin, Calendar, Phone, Mail, ArrowLeft, Star } from 'lucide-react';
import { useApp } from '../context/AppContext';

const Matches = ({ onBack }) => {
  const { likedPets } = useApp();
  const [selectedPet, setSelectedPet] = useState(null);

  const getAgeText = (age) => {
    if (age < 1) return `${Math.round(age * 12)} months`;
    return `${age} year${age > 1 ? 's' : ''}`;
  };

  if (selectedPet) {
    return (
      <motion.div
        initial={{ opacity: 0, x: 50 }}
        animate={{ opacity: 1, x: 0 }}
        className="min-h-screen bg-gray-50 p-4"
      >
        <div className="max-w-2xl mx-auto">
          <button
            onClick={() => setSelectedPet(null)}
            className="flex items-center text-gray-600 hover:text-gray-800 mb-6 transition-colors"
          >
            <ArrowLeft className="w-5 h-5 mr-2" />
            Back to Matches
          </button>

          <div className="bg-white rounded-2xl shadow-xl overflow-hidden">
            <div className="relative h-80">
            <img
              src={selectedPet.images?.[0] || selectedPet.imagePet || 'https://via.placeholder.com/400x300?text=Pet+Photo'}
              alt={selectedPet.name}
              className="w-full h-full object-cover"
              onError={(e) => {
                e.target.src = 'https://via.placeholder.com/400x300?text=Pet+Photo';
              }}
            />
              <div className="absolute top-4 right-4 bg-red-500 text-white p-2 rounded-full">
                <Heart className="w-5 h-5 fill-current" />
              </div>
            </div>

            <div className="p-6">
              <div className="flex items-center justify-between mb-4">
                <h1 className="text-3xl font-bold text-gray-800">{selectedPet.name}</h1>
                <div className="flex items-center bg-yellow-100 text-yellow-800 px-3 py-1 rounded-full">
                  <Star className="w-4 h-4 mr-1 fill-current" />
                  <span className="text-sm font-medium">Match</span>
                </div>
              </div>

              <div className="space-y-4">
                <div className="flex items-center text-gray-600">
                  <Calendar className="w-5 h-5 mr-3" />
                  <span>{getAgeText(selectedPet.age)} old {selectedPet.breed}</span>
                </div>
                
                <div className="flex items-center text-gray-600">
                  <MapPin className="w-5 h-5 mr-3" />
                  <span>{selectedPet.location}</span>
                </div>

                <div className="bg-gray-50 rounded-lg p-4">
                  <h3 className="font-semibold text-gray-800 mb-2">About {selectedPet.name}</h3>
                  <p className="text-gray-600 leading-relaxed">{selectedPet.description}</p>
                </div>

                {selectedPet.personality && (
                  <div>
                    <h3 className="font-semibold text-gray-800 mb-2">Personality</h3>
                    <div className="flex flex-wrap gap-2">
                      {selectedPet.personality.map((trait, index) => (
                        <span
                          key={index}
                          className="bg-blue-100 text-blue-800 text-sm px-3 py-1 rounded-full"
                        >
                          {trait}
                        </span>
                      ))}
                    </div>
                  </div>
                )}

                <div className="border-t pt-4">
                  <h3 className="font-semibold text-gray-800 mb-4">Next Steps</h3>
                  <div className="space-y-3">
                    <button className="w-full bg-gradient-to-r from-primary-500 to-secondary-500 text-white py-3 px-6 rounded-lg font-medium hover:from-primary-600 hover:to-secondary-600 transition-all flex items-center justify-center">
                      <Phone className="w-5 h-5 mr-2" />
                      Contact {selectedPet.shelter}
                    </button>
                    <button className="w-full bg-gray-100 text-gray-800 py-3 px-6 rounded-lg font-medium hover:bg-gray-200 transition-all flex items-center justify-center">
                      <Mail className="w-5 h-5 mr-2" />
                      Send Inquiry
                    </button>
                  </div>
                  
                  {selectedPet.adoptionFee && (
                    <div className="mt-4 text-center">
                      <span className="text-lg font-bold text-primary-600">
                        Adoption Fee: ${selectedPet.adoptionFee}
                      </span>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      </motion.div>
    );
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className="min-h-screen bg-gray-50 p-4"
    >
      <div className="max-w-4xl mx-auto">
        <div className="flex items-center justify-between mb-8">
          <div>
            <h1 className="text-3xl font-bold text-gray-800">Your Matches</h1>
            <p className="text-gray-600 mt-1">
              {likedPets.length} {likedPets.length === 1 ? 'pet' : 'pets'} waiting for you!
            </p>
          </div>
          
          {onBack && (
            <button
              onClick={onBack}
              className="flex items-center text-gray-600 hover:text-gray-800 transition-colors"
            >
              <ArrowLeft className="w-5 h-5 mr-2" />
              Back to Swiping
            </button>
          )}
        </div>

        {likedPets.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            <AnimatePresence>
              {likedPets.map((pet, index) => (
                <motion.div
                  key={pet.id}
                  initial={{ opacity: 0, scale: 0.8 }}
                  animate={{ opacity: 1, scale: 1 }}
                  exit={{ opacity: 0, scale: 0.8 }}
                  transition={{ delay: index * 0.1 }}
                  className="bg-white rounded-xl shadow-lg overflow-hidden hover:shadow-xl transition-shadow cursor-pointer"
                  onClick={() => setSelectedPet(pet)}
                >
                  <div className="relative h-48">
                    <img
                      src={pet.images?.[0] || pet.imagePet}
                      alt={pet.name}
                      className="w-full h-full object-cover"
                      onError={(e) => {
                        e.target.src = 'https://via.placeholder.com/300x200?text=Pet+Photo';
                      }}
                    />
                    <div className="absolute top-3 right-3 bg-red-500 text-white p-2 rounded-full">
                      <Heart className="w-4 h-4 fill-current" />
                    </div>
                    {pet.featured && (
                      <div className="absolute top-3 left-3 bg-yellow-400 text-yellow-800 px-2 py-1 rounded-full text-xs font-medium">
                        Featured
                      </div>
                    )}
                  </div>
                  
                  <div className="p-4">
                    <div className="flex items-center justify-between mb-2">
                      <h3 className="text-xl font-bold text-gray-800">{pet.name}</h3>
                      <span className="text-sm text-gray-500">{getAgeText(pet.age)}</span>
                    </div>
                    
                    <p className="text-gray-600 text-sm mb-3">
                      {pet.breed} • {pet.size}
                    </p>
                    
                    <div className="flex items-center text-gray-500 text-sm mb-3">
                      <MapPin className="w-4 h-4 mr-1" />
                      <span>{pet.location}</span>
                    </div>
                    
                    <p className="text-gray-600 text-sm line-clamp-2 mb-3">
                      {pet.description}
                    </p>
                    
                    {pet.personality && (
                      <div className="flex flex-wrap gap-1 mb-3">
                        {pet.personality.slice(0, 2).map((trait, index) => (
                          <span
                            key={index}
                            className="bg-blue-100 text-blue-800 text-xs px-2 py-1 rounded-full"
                          >
                            {trait}
                          </span>
                        ))}
                        {pet.personality.length > 2 && (
                          <span className="text-xs text-gray-500 px-2 py-1">
                            +{pet.personality.length - 2}
                          </span>
                        )}
                      </div>
                    )}
                    
                    <div className="flex items-center justify-between">
                      {pet.adoptionFee && (
                        <span className="text-primary-600 font-bold">
                          ${pet.adoptionFee}
                        </span>
                      )}
                      <button className="bg-gradient-to-r from-primary-500 to-secondary-500 text-white px-4 py-2 rounded-lg text-sm font-medium hover:from-primary-600 hover:to-secondary-600 transition-all">
                        Contact
                      </button>
                    </div>
                  </div>
                </motion.div>
              ))}
            </AnimatePresence>
          </div>
        ) : (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="text-center py-20"
          >
            <div className="w-32 h-32 bg-gray-200 rounded-full mx-auto mb-6 flex items-center justify-center">
              <Heart className="w-16 h-16 text-gray-400" />
            </div>
            <h2 className="text-2xl font-bold text-gray-800 mb-4">
              No matches yet!
            </h2>
            <p className="text-gray-600 max-w-md mx-auto mb-8">
              Start swiping to find your perfect pet companion. When you like a pet, they'll appear here.
            </p>
            {onBack && (
              <button
                onClick={onBack}
                className="bg-gradient-to-r from-primary-500 to-secondary-500 text-white px-6 py-3 rounded-lg font-medium hover:from-primary-600 hover:to-secondary-600 transition-all"
              >
                Start Swiping
              </button>
            )}
          </motion.div>
        )}
      </div>
    </motion.div>
  );
};

export default Matches;
