import React from 'react';
import { motion } from 'framer-motion';
import { Heart, Search, User, Settings, Undo2, X } from 'lucide-react';
import { useApp } from '../context/AppContext';

const Navigation = ({ currentView, onViewChange, onSwipeLeft, onSwipeRight, onGoBack, canGoBack }) => {
  const { likedPets } = useApp();

  const navigationItems = [
    { id: 'swipe', icon: Search, label: 'Discover', badge: null },
    { id: 'matches', icon: Heart, label: 'Matches', badge: likedPets.length },
    { id: 'profile', icon: User, label: 'Profile', badge: null },
    { id: 'settings', icon: Settings, label: 'Settings', badge: null },
  ];

  return (
    <>
      {/* Swipe Action Buttons - Only show on swipe view */}
      {currentView === 'swipe' && (
        <div className="fixed bottom-32 left-1/2 transform -translate-x-1/2 z-10">
          <div className="flex items-center space-x-4">
            {/* Go Back Button */}
            <motion.button
              onClick={onGoBack}
              disabled={!canGoBack}
              className={`w-14 h-14 rounded-full flex items-center justify-center transition-all ${
                canGoBack 
                  ? 'bg-gray-500 text-white hover:bg-gray-600 shadow-lg' 
                  : 'bg-gray-200 text-gray-400 cursor-not-allowed'
              }`}
              whileHover={canGoBack ? { scale: 1.1 } : {}}
              whileTap={canGoBack ? { scale: 0.9 } : {}}
            >
              <Undo2 className="w-6 h-6" />
            </motion.button>

            {/* Pass Button */}
            <motion.button
              onClick={onSwipeLeft}
              className="w-16 h-16 bg-gradient-to-r from-red-400 to-pink-500 text-white rounded-full flex items-center justify-center shadow-lg hover:from-red-500 hover:to-pink-600 transition-all"
              whileHover={{ scale: 1.1 }}
              whileTap={{ scale: 0.9 }}
            >
              <X className="w-8 h-8" />
            </motion.button>

            {/* Like Button */}
            <motion.button
              onClick={onSwipeRight}
              className="w-16 h-16 bg-gradient-to-r from-green-400 to-blue-500 text-white rounded-full flex items-center justify-center shadow-lg hover:from-green-500 hover:to-blue-600 transition-all"
              whileHover={{ scale: 1.1 }}
              whileTap={{ scale: 0.9 }}
            >
              <Heart className="w-8 h-8" />
            </motion.button>
          </div>
        </div>
      )}

      {/* Bottom Navigation */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 px-4 py-2 z-20">
        <div className="flex justify-around items-center max-w-md mx-auto">
          {navigationItems.map((item) => {
            const Icon = item.icon;
            const isActive = currentView === item.id;
            
            return (
              <motion.button
                key={item.id}
                onClick={() => onViewChange(item.id)}
                className={`relative flex flex-col items-center p-2 transition-all ${
                  isActive 
                    ? 'text-primary-600' 
                    : 'text-gray-500 hover:text-gray-700'
                }`}
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
              >
                <div className="relative">
                  <Icon className={`w-6 h-6 ${isActive ? 'fill-current' : ''}`} />
                  {item.badge && item.badge > 0 && (
                    <div className="absolute -top-2 -right-2 bg-red-500 text-white text-xs rounded-full w-5 h-5 flex items-center justify-center">
                      {item.badge > 99 ? '99+' : item.badge}
                    </div>
                  )}
                </div>
                <span className="text-xs mt-1">{item.label}</span>
                
                {/* Active indicator */}
                {isActive && (
                  <motion.div
                    layoutId="activeTab"
                    className="absolute -bottom-2 left-1/2 transform -translate-x-1/2 w-1 h-1 bg-primary-600 rounded-full"
                    initial={false}
                    transition={{ type: "spring", stiffness: 500, damping: 30 }}
                  />
                )}
              </motion.button>
            );
          })}
        </div>
      </nav>
    </>
  );
};

export default Navigation;
