import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Heart, MapPin, Info, Award, Shield, Home, Calendar, Weight } from 'lucide-react';

const PetCard = ({ pet, onSwipe, swipeDirection }) => {
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [showDetails, setShowDetails] = useState(false);

  if (!pet) return null;

  const images = pet.images || [pet.imagePet];
  const currentImage = images[currentImageIndex];

  const nextImage = () => {
    setCurrentImageIndex((prev) => (prev + 1) % images.length);
  };

  const prevImage = () => {
    setCurrentImageIndex((prev) => (prev - 1 + images.length) % images.length);
  };

  const getAgeText = (age) => {
    if (age < 1) return `${Math.round(age * 12)} months`;
    return `${age} year${age > 1 ? 's' : ''}`;
  };

  return (
    <motion.div
      className="relative w-full max-w-sm mx-auto bg-white rounded-2xl shadow-2xl overflow-hidden"
      initial={{ scale: 0.8, opacity: 0 }}
      animate={{ 
        scale: 1, 
        opacity: 1,
        x: swipeDirection === 'left' ? -100 : swipeDirection === 'right' ? 100 : 0,
        rotate: swipeDirection === 'left' ? -10 : swipeDirection === 'right' ? 10 : 0
      }}
      transition={{ duration: 0.3 }}
      style={{ height: '600px' }}
    >
      {/* Image Container */}
      <div className="relative h-96 overflow-hidden">
        <img
          src={currentImage}
          alt={pet.name}
          className="w-full h-full object-cover"
          onError={(e) => {
            e.target.src = 'https://via.placeholder.com/400x400?text=Pet+Photo';
          }}
        />
        
        {/* Image Navigation */}
        {images.length > 1 && (
          <>
            <button
              onClick={prevImage}
              className="absolute left-2 top-1/2 transform -translate-y-1/2 bg-black bg-opacity-50 text-white p-2 rounded-full hover:bg-opacity-70 transition-all"
            >
              ←
            </button>
            <button
              onClick={nextImage}
              className="absolute right-2 top-1/2 transform -translate-y-1/2 bg-black bg-opacity-50 text-white p-2 rounded-full hover:bg-opacity-70 transition-all"
            >
              →
            </button>
            
            {/* Image indicators */}
            <div className="absolute bottom-4 left-1/2 transform -translate-x-1/2 flex space-x-2">
              {images.map((_, index) => (
                <div
                  key={index}
                  className={`w-2 h-2 rounded-full transition-all ${
                    index === currentImageIndex ? 'bg-white' : 'bg-white bg-opacity-50'
                  }`}
                />
              ))}
            </div>
          </>
        )}
        
        {/* Featured Badge */}
        {pet.featured && (
          <div className="absolute top-4 left-4 bg-gradient-to-r from-yellow-400 to-orange-500 text-white px-3 py-1 rounded-full text-sm font-medium flex items-center">
            <Award className="w-4 h-4 mr-1" />
            Featured
          </div>
        )}

        {/* Details Toggle */}
        <button
          onClick={() => setShowDetails(!showDetails)}
          className="absolute top-4 right-4 bg-black bg-opacity-50 text-white p-2 rounded-full hover:bg-opacity-70 transition-all"
        >
          <Info className="w-4 h-4" />
        </button>
      </div>

      {/* Pet Information */}
      <div className="p-6 h-52 overflow-y-auto">
        <div className="flex items-center justify-between mb-3">
          <h2 className="text-2xl font-bold text-gray-800">{pet.name}</h2>
          <div className="flex items-center text-gray-600">
            <Calendar className="w-4 h-4 mr-1" />
            <span className="text-sm">{getAgeText(pet.age)}</span>
          </div>
        </div>

        <div className="space-y-2 mb-4">
          <div className="flex items-center text-gray-600">
            <span className="font-medium">{pet.breed}</span>
            <span className="mx-2">•</span>
            <span className="text-sm">{pet.gender}</span>
            <span className="mx-2">•</span>
            <span className="text-sm">{pet.size}</span>
          </div>
          
          <div className="flex items-center text-gray-600">
            <MapPin className="w-4 h-4 mr-1" />
            <span className="text-sm">{pet.location}</span>
          </div>

          {pet.weight && (
            <div className="flex items-center text-gray-600">
              <Weight className="w-4 h-4 mr-1" />
              <span className="text-sm">{pet.weight}</span>
            </div>
          )}
        </div>

        {/* Show details panel */}
        {showDetails ? (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            className="space-y-4"
          >
            <div>
              <h3 className="font-semibold text-gray-800 mb-2">About {pet.name}</h3>
              <p className="text-gray-600 text-sm leading-relaxed">{pet.description}</p>
            </div>

            {pet.personality && pet.personality.length > 0 && (
              <div>
                <h3 className="font-semibold text-gray-800 mb-2">Personality</h3>
                <div className="flex flex-wrap gap-2">
                  {pet.personality.map((trait, index) => (
                    <span
                      key={index}
                      className="bg-blue-100 text-blue-800 text-xs px-2 py-1 rounded-full"
                    >
                      {trait}
                    </span>
                  ))}
                </div>
              </div>
            )}

            {pet.goodWith && pet.goodWith.length > 0 && (
              <div>
                <h3 className="font-semibold text-gray-800 mb-2">Good With</h3>
                <div className="flex flex-wrap gap-2">
                  {pet.goodWith.map((item, index) => (
                    <span
                      key={index}
                      className="bg-green-100 text-green-800 text-xs px-2 py-1 rounded-full"
                    >
                      {item}
                    </span>
                  ))}
                </div>
              </div>
            )}

            {/* Health & Care Info */}
            <div className="grid grid-cols-3 gap-4 pt-4 border-t">
              <div className="text-center">
                <div className={`w-8 h-8 rounded-full mx-auto mb-1 flex items-center justify-center ${
                  pet.vaccinated ? 'bg-green-100' : 'bg-red-100'
                }`}>
                  <Shield className={`w-4 h-4 ${pet.vaccinated ? 'text-green-600' : 'text-red-600'}`} />
                </div>
                <span className="text-xs text-gray-600">Vaccinated</span>
              </div>
              <div className="text-center">
                <div className={`w-8 h-8 rounded-full mx-auto mb-1 flex items-center justify-center ${
                  pet.spayed ? 'bg-green-100' : 'bg-red-100'
                }`}>
                  <Heart className={`w-4 h-4 ${pet.spayed ? 'text-green-600' : 'text-red-600'}`} />
                </div>
                <span className="text-xs text-gray-600">Spayed/Neutered</span>
              </div>
              <div className="text-center">
                <div className={`w-8 h-8 rounded-full mx-auto mb-1 flex items-center justify-center ${
                  pet.houseTrained ? 'bg-green-100' : 'bg-red-100'
                }`}>
                  <Home className={`w-4 h-4 ${pet.houseTrained ? 'text-green-600' : 'text-red-600'}`} />
                </div>
                <span className="text-xs text-gray-600">House Trained</span>
              </div>
            </div>

            {pet.adoptionFee && (
              <div className="text-center pt-4 border-t">
                <span className="text-lg font-bold text-primary-600">
                  Adoption Fee: ${pet.adoptionFee}
                </span>
              </div>
            )}

            {pet.shelter && (
              <div className="text-center text-sm text-gray-600">
                Available at {pet.shelter}
              </div>
            )}
          </motion.div>
        ) : (
          <div className="space-y-3">
            <p className="text-gray-600 text-sm leading-relaxed line-clamp-3">
              {pet.description}
            </p>
            
            {pet.personality && pet.personality.length > 0 && (
              <div className="flex flex-wrap gap-2">
                {pet.personality.slice(0, 3).map((trait, index) => (
                  <span
                    key={index}
                    className="bg-blue-100 text-blue-800 text-xs px-2 py-1 rounded-full"
                  >
                    {trait}
                  </span>
                ))}
                {pet.personality.length > 3 && (
                  <span className="text-xs text-gray-500 px-2 py-1">
                    +{pet.personality.length - 3} more
                  </span>
                )}
              </div>
            )}

            {pet.adoptionFee && (
              <div className="text-center pt-2">
                <span className="text-lg font-bold text-primary-600">
                  ${pet.adoptionFee}
                </span>
              </div>
            )}
          </div>
        )}
      </div>
    </motion.div>
  );
};

export default PetCard;
