import React, { createContext, useContext, useReducer, useEffect } from 'react';
import { petData, defaultUserData } from '../data';

const AppContext = createContext();

const initialState = {
  user: defaultUserData,
  pets: petData,
  currentPetIndex: 0,
  likedPets: [],
  passedPets: [],
  isOnboarded: false,
  filters: {
    petTypes: [],
    sizes: [],
    ageRange: [0, 15],
    location: '',
    maxDistance: 50,
    showOnlyFeatured: false
  },
  swipeDirection: null,
  isLoading: false,
  error: null
};

function appReducer(state, action) {
  switch (action.type) {
    case 'SET_USER':
      return {
        ...state,
        user: action.payload,
        isOnboarded: true
      };
    
    case 'SET_ONBOARDED':
      return {
        ...state,
        isOnboarded: action.payload
      };
    
    case 'LIKE_PET':
      const likedPet = state.pets[state.currentPetIndex];
      if (likedPet) {
        return {
          ...state,
          likedPets: [...state.likedPets, likedPet],
          currentPetIndex: state.currentPetIndex + 1,
          swipeDirection: 'right'
        };
      }
      return state;
    
    case 'PASS_PET':
      const passedPet = state.pets[state.currentPetIndex];
      if (passedPet) {
        return {
          ...state,
          passedPets: [...state.passedPets, passedPet],
          currentPetIndex: state.currentPetIndex + 1,
          swipeDirection: 'left'
        };
      }
      return state;
    
    case 'RESET_SWIPE_DIRECTION':
      return {
        ...state,
        swipeDirection: null
      };
    
    case 'SET_FILTERS':
      return {
        ...state,
        filters: { ...state.filters, ...action.payload }
      };
    
    case 'RESET_PETS':
      return {
        ...state,
        currentPetIndex: 0,
        likedPets: [],
        passedPets: []
      };
    
    case 'GO_BACK':
      if (state.currentPetIndex > 0) {
        const previousPet = state.pets[state.currentPetIndex - 1];
        return {
          ...state,
          currentPetIndex: state.currentPetIndex - 1,
          likedPets: state.likedPets.filter(pet => pet.id !== previousPet.id),
          passedPets: state.passedPets.filter(pet => pet.id !== previousPet.id)
        };
      }
      return state;
    
    case 'SET_LOADING':
      return {
        ...state,
        isLoading: action.payload
      };
    
    case 'SET_ERROR':
      return {
        ...state,
        error: action.payload
      };
    
    default:
      return state;
  }
}

export function AppProvider({ children }) {
  const [state, dispatch] = useReducer(appReducer, initialState);

  // Load state from localStorage on mount
  useEffect(() => {
    const savedState = localStorage.getItem('petTinderState');
    if (savedState) {
      try {
        const parsedState = JSON.parse(savedState);
        if (parsedState.user) {
          dispatch({ type: 'SET_USER', payload: parsedState.user });
        }
        if (parsedState.likedPets) {
          // Restore liked pets and current index
          parsedState.likedPets.forEach(pet => {
            dispatch({ type: 'LIKE_PET' });
          });
        }
      } catch (error) {
        console.error('Error loading saved state:', error);
      }
    }
  }, []);

  // Save state to localStorage when it changes
  useEffect(() => {
    const stateToSave = {
      user: state.user,
      likedPets: state.likedPets,
      currentPetIndex: state.currentPetIndex,
      isOnboarded: state.isOnboarded
    };
    localStorage.setItem('petTinderState', JSON.stringify(stateToSave));
  }, [state.user, state.likedPets, state.currentPetIndex, state.isOnboarded]);

  // Helper functions
  const likePet = () => {
    dispatch({ type: 'LIKE_PET' });
    setTimeout(() => dispatch({ type: 'RESET_SWIPE_DIRECTION' }), 300);
  };

  const passPet = () => {
    dispatch({ type: 'PASS_PET' });
    setTimeout(() => dispatch({ type: 'RESET_SWIPE_DIRECTION' }), 300);
  };

  const goBack = () => {
    dispatch({ type: 'GO_BACK' });
  };

  const setUser = (userData) => {
    dispatch({ type: 'SET_USER', payload: userData });
  };

  const setFilters = (filters) => {
    dispatch({ type: 'SET_FILTERS', payload: filters });
  };

  const resetPets = () => {
    dispatch({ type: 'RESET_PETS' });
  };

  const setOnboarded = (value) => {
    dispatch({ type: 'SET_ONBOARDED', payload: value });
  };

  // Get filtered pets based on current filters
  const getFilteredPets = () => {
    let filtered = state.pets;

    if (state.filters.petTypes.length > 0) {
      filtered = filtered.filter(pet => 
        state.filters.petTypes.includes(pet.type)
      );
    }

    if (state.filters.sizes.length > 0) {
      filtered = filtered.filter(pet => 
        state.filters.sizes.includes(pet.size)
      );
    }

    if (state.filters.ageRange) {
      filtered = filtered.filter(pet => 
        pet.age >= state.filters.ageRange[0] && 
        pet.age <= state.filters.ageRange[1]
      );
    }

    if (state.filters.showOnlyFeatured) {
      filtered = filtered.filter(pet => pet.featured);
    }

    return filtered;
  };

  const getCurrentPet = () => {
    const filteredPets = getFilteredPets();
    return filteredPets[state.currentPetIndex] || null;
  };

  const hasMorePets = () => {
    const filteredPets = getFilteredPets();
    return state.currentPetIndex < filteredPets.length;
  };

  const value = {
    ...state,
    likePet,
    passPet,
    goBack,
    setUser,
    setFilters,
    resetPets,
    setOnboarded,
    getCurrentPet,
    hasMorePets,
    getFilteredPets
  };

  return <AppContext.Provider value={value}>{children}</AppContext.Provider>;
}

export function useApp() {
  const context = useContext(AppContext);
  if (context === undefined) {
    throw new Error('useApp must be used within an AppProvider');
  }
  return context;
}
