import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Toaster } from 'react-hot-toast';
import { AppProvider, useApp } from './context/AppContext';
import Onboarding from './components/Onboarding';
import PetCard from './components/PetCard';
import Matches from './components/Adopted';
import Profile from './components/Profile';
import Navigation from './components/Navigation';
import './App.css';

function AppContent() {
  const { 
    isOnboarded, 
    getCurrentPet, 
    hasMorePets, 
    likePet, 
    passPet, 
    goBack, 
    currentPetIndex, 
    swipeDirection,
    user
  } = useApp();
  
  const [currentView, setCurrentView] = useState('swipe');

  if (!isOnboarded) {
    return <Onboarding />;
  }

  const currentPet = getCurrentPet();
  const canGoBack = currentPetIndex > 0;

  const handleSwipeLeft = () => {
    passPet();
  };

  const handleSwipeRight = () => {
    likePet();
  };

  const handleGoBack = () => {
    if (canGoBack) {
      goBack();
    }
  };

  const renderContent = () => {
    switch (currentView) {
      case 'swipe':
        return (
          <div className="min-h-screen bg-gradient-to-br from-pink-50 to-blue-50 flex flex-col items-center justify-center p-4 pb-32">
            {/* Header */}
            <div className="w-full max-w-md mb-8">
              <motion.div
                initial={{ opacity: 0, y: -20 }}
                animate={{ opacity: 1, y: 0 }}
                className="text-center"
              >
                <h1 className="text-2xl font-bold text-gray-800 mb-2">
                  Hi {user.name}! 👋
                </h1>
                <p className="text-gray-600">
                  Find your perfect companion
                </p>
              </motion.div>
            </div>

            {/* Pet Card */}
            <div className="w-full max-w-md">
              <AnimatePresence mode="wait">
                {hasMorePets() && currentPet ? (
                  <motion.div
                    key={currentPet.id}
                    initial={{ opacity: 0, scale: 0.8 }}
                    animate={{ opacity: 1, scale: 1 }}
                    exit={{ opacity: 0, scale: 0.8 }}
                    transition={{ duration: 0.3 }}
                  >
                    <PetCard 
                      pet={currentPet} 
                      swipeDirection={swipeDirection}
                    />
                  </motion.div>
                ) : (
                  <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="text-center py-20"
                  >
                    <div className="w-32 h-32 bg-gradient-to-br from-primary-400 to-secondary-400 rounded-full mx-auto mb-6 flex items-center justify-center">
                      <span className="text-4xl">🎉</span>
                    </div>
                    <h2 className="text-2xl font-bold text-gray-800 mb-4">
                      You've seen all the pets!
                    </h2>
                    <p className="text-gray-600 mb-8">
                      Check your matches or adjust your preferences to see more pets.
                    </p>
                    <button
                      onClick={() => setCurrentView('matches')}
                      className="bg-gradient-to-r from-primary-500 to-secondary-500 text-white px-6 py-3 rounded-lg font-medium hover:from-primary-600 hover:to-secondary-600 transition-all"
                    >
                      View Matches
                    </button>
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          </div>
        );
      
      case 'matches':
        return <Matches onBack={() => setCurrentView('swipe')} />;
      
      case 'profile':
        return <Profile />;
      
      case 'settings':
        return (
          <div className="min-h-screen bg-gray-50 flex items-center justify-center p-4">
            <div className="text-center">
              <h2 className="text-2xl font-bold text-gray-800 mb-4">Settings</h2>
              <p className="text-gray-600">Settings page coming soon!</p>
            </div>
          </div>
        );
      
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50">
      {renderContent()}
      
      <Navigation
        currentView={currentView}
        onViewChange={setCurrentView}
        onSwipeLeft={handleSwipeLeft}
        onSwipeRight={handleSwipeRight}
        onGoBack={handleGoBack}
        canGoBack={canGoBack}
      />
      
      <Toaster
        position="top-center"
        toastOptions={{
          duration: 2000,
          style: {
            background: '#363636',
            color: '#fff',
          },
        }}
      />
    </div>
  );
}

function App() {
  return (
    <AppProvider>
      <AppContent />
    </AppProvider>
  );
}

export default App;
